async () => {
  const deadline = Date.now() + 45000;
  while (Date.now() < deadline) {
    const loading = document.body.innerText.includes('AI 正在解析 Schema');
    if (!loading) return { ready: true };
    await new Promise(r => setTimeout(r, 2000));
  }
  return { ready: false };
}

() => {
  const out = {};
  // body/main background
  out.bodyBg = getComputedStyle(document.body).backgroundColor;
  const main = document.querySelector('main');
  out.mainBg = main ? getComputedStyle(main).backgroundColor : null;
  // SVG text elements (axis ticks, labels)
  const svgTexts = Array.from(document.querySelectorAll('svg text')).slice(0, 30).map(t => ({
    text: t.textContent.trim().slice(0, 12),
    fill: getComputedStyle(t).fill,
    opacity: getComputedStyle(t).opacity
  }));
  out.svgTexts = svgTexts;
  // chart container background
  const chartEl = document.querySelector('.recharts-wrapper') || document.querySelector('[class*=chart]');
  if (chartEl) {
    let el = chartEl, bgs = [];
    for (let i = 0; i < 5 && el; i++) { bgs.push(getComputedStyle(el).backgroundColor); el = el.parentElement; }
    out.chartBgChain = bgs;
  }
  return out;
}

() => {
  const out = {};
  // legend text
  const legendImgs = document.querySelectorAll('img[alt*="legend"]');
  out.legendCount = legendImgs.length;
  out.legendColors = Array.from(legendImgs).map(img => {
    const parent = img.closest('div');
    const sib = parent ? parent.textContent.trim() : '';
    const el = parent && parent.parentElement ? parent.parentElement : parent;
    return { label: sib, color: el ? getComputedStyle(el).color : null, parentBg: el ? getComputedStyle(el).backgroundColor : null };
  });
  // grid lines: look for svg lines/paths with stroke
  const lines = Array.from(document.querySelectorAll('svg line, svg path')).slice(0, 400);
  const strokes = {};
  lines.forEach(l => {
    const s = getComputedStyle(l).stroke;
    if (s && s !== 'none') strokes[s] = (strokes[s] || 0) + 1;
  });
  out.strokeCounts = strokes;
  // find the assistant message card containing "AI 归因分析"
  const all = Array.from(document.querySelectorAll('div'));
  const card = all.find(d => d.textContent.includes('年度平均ROI') && d.textContent.includes('明细数据集'));
  if (card) {
    let el = card, chain = [];
    for (let i = 0; i < 8 && el; i++) {
      const cs = getComputedStyle(el);
      if (cs.backgroundColor !== 'rgba(0, 0, 0, 0)') chain.push(cs.backgroundColor);
      el = el.parentElement;
    }
    out.cardBgChain = chain;
    out.cardTextColor = getComputedStyle(card).color;
  }
  // table text
  const table = document.querySelector('table');
  if (table) {
    out.tableColor = getComputedStyle(table).color;
    const firstTd = table.querySelector('td');
    out.tdColor = firstTd ? getComputedStyle(firstTd).color : null;
    out.tdBg = firstTd ? getComputedStyle(firstTd).backgroundColor : null;
    const th = table.querySelector('th');
    out.thColor = th ? getComputedStyle(th).color : null;
    out.thBg = th ? getComputedStyle(th).backgroundColor : null;
  }
  return out;
}

() => {
