  if (h) {
    let el = h, chain = [];
    for (let i = 0; i < 6 && el; i++) {
      const cs = getComputedStyle(el);
      chain.push({ cls: (el.className || '').toString().slice(0, 60), bg: cs.backgroundColor });
      el = el.parentElement;
