() => {
  const out = {};
  const demo = Array.from(document.querySelectorAll('*')).find(e => e.children.length === 0 && e.textContent.startsWith('演示数据'));
  if (demo) {
    let el = demo;
    for (let i = 0; i < 4 && el; i++) {
      const bg = getComputedStyle(el).backgroundColor;
      if (bg !== 'rgba(0, 0, 0, 0)') { out.demoContainerCls = (el.className || '').toString().slice(0, 100); out.demoBg = bg; break; }
      el = el.parentElement;
    }
    out.demoTextCls = (demo.className || '').toString().slice(0, 100);
  }
  // blend demo bg over white to get effective color
  const parse = (c) => {
    const m = c.match(/oklab\(([\d.]+)\s+(-?[\d.]+)\s+(-?[\d.]+)\s*\/\s*([\d.]+)\)/);
    return m ? { L: +m[1], a: +m[2], b: +m[3], alpha: +m[4] } : null;
  };
  const o = parse(out.demoBg || '');
  if (o) {
    // oklab to approx sRGB
    const L = o.L, a = o.a, b = o.b;
    const l_ = L + 0.3963377774 * a + 0.2158037573 * b;
    const m_ = L - 0.1055613458 * a - 0.0638541728 * b;
    const s_ = L - 0.0894841775 * a - 1.2914855480 * b;
    const l = l_ ** 3, m = m_ ** 3, s = s_ ** 3;
    let r = +4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s;
    let g = -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s;
    let bl = -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s;
    const gam = (c) => { c = Math.max(0, Math.min(1, c)); return c <= 0.0031308 ? 12.92 * c : 1.055 * Math.pow(c, 1 / 2.4) - 0.055; };
    r = gam(r); g = gam(g); bl = gam(bl);
    const blend = (c) => Math.round(c * o.alpha + 1 * (1 - o.alpha)) * 255;
    out.demoEffectiveBg = [blend(r), blend(g), blend(bl)];
    // text amber-600 = 217,119,6
    const lum = (R, G, B) => { const f = (v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }; return 0.2126 * f(R) + 0.7152 * f(G) + 0.0722 * f(B); };
    const L1 = lum(217, 119, 6), L2 = lum(blend(r), blend(g), blend(bl));
    out.demoContrast = ((Math.max(L1, L2) + 0.05) / (Math.min(L1, L2) + 0.05)).toFixed(2);
  }
  // AI interpretation section colors
  const aiHead = Array.from(document.querySelectorAll('*')).find(e => e.children.length === 0 && e.textContent.trim() === 'AI 归因分析与决策提示:');
  if (aiHead) {
    out.aiHeadColor = getComputedStyle(aiHead).color;
    let el = aiHead, chain = [];
    for (let i = 0; i < 4 && el; i++) { const bg = getComputedStyle(el).backgroundColor; if (bg !== 'rgba(0, 0, 0, 0)') chain.push(bg); el = el.parentElement; }
    out.aiHeadBgChain = chain;
  }
  const item1 = Array.from(document.querySelectorAll('*')).find(e => e.children.length === 0 && e.textContent.startsWith('效能拐点明确'));
  if (item1) out.aiItemColor = getComputedStyle(item1).color;
  return out;
}

