  const badge = Array.from(container.querySelectorAll('*')).find(e => e.children.length === 0 && e.textContent.trim() === '12');
  if (badge) {
    out.badgeColor = getComputedStyle(badge).color;
    out.badgeBg = getComputedStyle(badge).backgroundColor;
    out.badgeCls = (badge.className || '').toString().slice(0, 100);
