  const cs = getComputedStyle(el);
  return { tag: el.tagName, cls: (el.className.baseVal !== undefined ? el.className.baseVal : el.className).toString().slice(0, 100), bg: cs.backgroundColor, color: cs.color, text: el.textContent.slice(0, 30) };
