() => {
  const slide = document.querySelector('.recharts-brush-slide');
  const cs = getComputedStyle(slide);
  const brush = document.querySelector('.recharts-brush');
  const texts = brush ? Array.from(brush.querySelectorAll('text')).map(t => ({ t: t.textContent, fill: getComputedStyle(t).fill })) : [];
  const rects = brush ? Array.from(brush.querySelectorAll('rect')).map(r => ({ fill: getComputedStyle(r).fill, stroke: getComputedStyle(r).stroke, cls: r.getAttribute('class') || '' })) : [];
  return { slideFill: cs.fill, slideStroke: cs.stroke, texts, rects: rects.slice(0, 6) };
}

() => {
  const region = document.querySelector('[aria-label="query-result-card"]');
  const imgs = Array.from(region.querySelectorAll('img')).map(i => ({ alt: i.alt, aria: i.getAttribute('aria-label'), src: (i.src || '').slice(0, 60), w: i.width, h: i.height }));
  return imgs.slice(0, 6);
}

() => {
  // find scrollable ancestor of the result card
  const region = document.querySelector('[aria-label="query-result-card"]');
  let el = region.parentElement, scrollers = [];
  while (el && el !== document.body) {
    const cs = getComputedStyle(el);
    if (/(auto|scroll)/.test(cs.overflowY)) scrollers.push(el);
    el = el.parentElement;
  }
  window.__savedStyles = scrollers.map(s => ({ s, ov: s.style.overflowY, h: s.style.height, mh: s.style.maxHeight }));
  scrollers.forEach(s => { s.style.overflowY = 'visible'; s.style.height = 'auto'; s.style.maxHeight = 'none'; });
  return { count: scrollers.length, classes: scrollers.map(s => s.className.toString().slice(0, 60)) };
}

() => {
  (window.__savedStyles || []).forEach(({ s, ov, h, mh }) => { s.style.overflowY = ov; s.style.height = h; s.style.maxHeight = mh; });
  window.__savedStyles = null;
  return { restored: true };
}
